def cases():
    rows = []
    for family, message, amount, approved, labels, dependency in SEEDS:
        for index, (tenant, version) in enumerate(TARGETS):
            context = {"currency": "USD", "supervisor_approved": approved}
            if amount is not None:
                context["fee_amount"] = amount
            rows.append({"id": f"{family}-{tenant}-{version}", "family_id": family,
                         "message": message, "context": context, "tenant": tenant,
                         "version": version, "expected": labels[index], "dependency": dependency,
                         "provenance": "manually specified synthetic smoke benchmark"})
    return rows
